rule "pve_parse_backup_job_vmids"
when
  to_string($message.app) == "pve" AND
  contains(to_string($message.message), "starting new backup job: vzdump ")
then
  let g = grok(pattern: "starting new backup job: vzdump %{DATA:backup_job_vmids} --", value: to_string($message.message), only_named_captures: true);
  set_fields(g);
  set_field("pve_event", "backup_job_start");
end

rule "pve_parse_pvedaemon_auth"
when
  to_string($message.pve_app) == "pvedaemon" AND
  contains(to_string($message.message), "successful auth for user")
then
  let g = grok(pattern: "<%{DATA:auth_actor}> successful auth for user '%{DATA:auth_target_user}'", value: to_string($message.message), only_named_captures: true);
  set_fields(g);
  set_field("auth_result", "success");
  set_field("pve_event", "auth");
end

rule "pve_parse_vncproxy"
when
  to_string($message.app) == "pve" AND
  to_string($message.pve_app) == "pvedaemon" AND
  contains(to_string($message.message), "vncproxy:")
then
  let g = grok(pattern: "vncproxy:%{NONNEGINT:VMID:int}:", value: to_string($message.message), only_named_captures: true);
  set_fields(g);
  set_field("pve_event", "vnc_console");
end

rule "pve_parse_pvestatd_status"
when
  to_string($message.pve_app) == "pvestatd" AND
  contains(to_string($message.message), "status update time")
then
  let g = grok(pattern: "status update time \\(%{NUMBER:status_update_seconds:float} seconds\\)", value: to_string($message.message), only_named_captures: true);
  set_fields(g);
  set_field("pve_event", "pvestatd_status");
end

rule "pve_parse_upid"
when
  to_string($message.app) == "pve" AND
  contains(to_string($message.message), "UPID:")
then
  let m = to_string($message.message);
  let g_all = grok(pattern: "UPID:%{HOSTNAME:upid_node}:%{BASE16NUM:upid_pid}:%{BASE16NUM:upid_pstart}:%{BASE16NUM:upid_starttime}:%{DATA:tasktype}:%{DATA:upid_wid}:%{DATA:upid_user}:", value: m, only_named_captures: true);
  set_fields(g_all);
  let g_vmid = grok(pattern: "UPID:%{HOSTNAME}:%{BASE16NUM}:%{BASE16NUM}:%{BASE16NUM}:%{DATA}:%{NONNEGINT:VMID:int}:", value: m, only_named_captures: true);
  set_fields(g_vmid);
end

rule "pve_parse_pvestatd_error"
when
  to_string($message.pve_app) == "pvestatd" AND
  contains(to_string($message.message), "HTTP ")
then
  let g = grok(pattern: "HTTP %{NUMBER:pvestatd_http_code:int}: %{GREEDYDATA:pvestatd_error}", value: to_string($message.message), only_named_captures: true);
  set_fields(g);
  set_field("pve_event", "pvestatd_error");
end

rule "pve_parse_qmeventd"
when
  to_string($message.pve_app) == "qmeventd" AND
  contains(to_string($message.message), "cleanup for ")
then
  let g = grok(pattern: "%{WORD:qmeventd_action} cleanup for %{NONNEGINT:VMID:int}", value: to_string($message.message), only_named_captures: true);
  set_fields(g);
  set_field("pve_event", "qmeventd_cleanup");
end

rule "pve_parse_backup_starting"
when
  to_string($message.app) == "pve" AND
  contains(to_string($message.message), "Starting Backup of VM ")
then
  let g = grok(pattern: "Starting Backup of VM %{NONNEGINT:VMID:int} \\(%{WORD:vm_type}\\)", value: to_string($message.message), only_named_captures: true);
  set_fields(g);
  set_field("pve_event", "backup_start");
end

rule "pve_legacy_user_realm_pid"
when
  has_field("upid_user")
then
  set_field("pid", to_string($message.upid_pid, ""));
  let g = grok(pattern: "%{DATA:user}@%{GREEDYDATA:realm}", value: to_string($message.upid_user, ""), only_named_captures: true);
  set_fields(g);
end

rule "pve_parse_backup_finished"
when
  to_string($message.app) == "pve" AND
  contains(to_string($message.message), "Finished Backup of VM ")
then
  let g = grok(pattern: "Finished Backup of VM %{NONNEGINT:VMID:int} \\(%{DATA:backup_duration}\\)", value: to_string($message.message), only_named_captures: true);
  set_fields(g);
  set_field("pve_event", "backup_finished");
end

rule "pve_parse_pveproxy_worker"
when
  to_string($message.pve_app) == "pveproxy" AND
  contains(to_string($message.message), "worker ")
then
  let g = grok(pattern: "worker %{NONNEGINT:pveproxy_worker_pid:int} %{WORD:pveproxy_worker_action}", value: to_string($message.message), only_named_captures: true);
  set_fields(g);
  set_field("pve_event", "pveproxy_worker");
end

rule "pve_parse_replication_error"
when
  to_string($message.pve_app) == "pvescheduler" AND
  contains(to_string($message.message), "replication job error")
then
  let g = grok(pattern: "%{NONNEGINT:VMID:int}-%{NONNEGINT:replication_job_idx:int}: %{GREEDYDATA:replication_error}", value: to_string($message.message), only_named_captures: true);
  set_fields(g);
  set_field("pve_event", "replication_error");
end

rule "pve_parse_backup_error"
when
  to_string($message.app) == "pve" AND
  contains(to_string($message.message), "ERROR: Backup of VM ")
then
  let g = grok(pattern: "ERROR: Backup of VM %{NONNEGINT:VMID:int} failed - %{GREEDYDATA:backup_error}", value: to_string($message.message), only_named_captures: true);
  set_fields(g);
  set_field("pve_event", "backup_error");
end

rule "pve_parse_oom"
when
  to_string($message.app) == "pve" AND
  contains(to_string($message.message), "oom-kill")
then
  let g1 = grok(pattern: "task=%{DATA:oom_task_name},", value: to_string($message.message), only_named_captures: true);
  let g2 = grok(pattern: "oom_memcg=%{DATA:oom_cgroup},", value: to_string($message.message), only_named_captures: true);
  set_fields(g1);
  set_fields(g2);
  set_field("pve_event", "oom_kill");
end
